const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var hongKong = ee.Geometry.Polygon([
    [[113.8, 22.15], [114.4, 22.15], [114.4, 22.55], [113.8, 22.55], [113.8, 22.15]]
  ]);

  var period1_start = '2020-02-10';
  var period1_end = '2020-02-25';
  var period2_start = '2020-04-20';
  var period2_end = '2020-05-12';

  // 2. Data Acquisition
  var no2_col1 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(period1_start, period1_end)
    .filterBounds(hongKong);

  var no2_col2 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(period2_start, period2_end)
    .filterBounds(hongKong);

  // Check collection sizes
  var size1 = no2_col1.size().getInfo();
  var size2 = no2_col2.size().getInfo();

  print('Period 1 (Feb 10-25) Images: ' + size1);
  print('Period 2 (Apr 20-May 12) Images: ' + size2);

  if (size1 === 0 || size2 === 0) {
    print('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Calculate mean NO2 for each period
  var mean_no2_1 = no2_col1.mean().select('NO2_column_number_density');
  var mean_no2_2 = no2_col2.mean().select('NO2_column_number_density');

  // Check pixel counts
  var count1 = mean_no2_1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  var count2 = mean_no2_2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  print('Period 1 Valid Pixels: ' + count1);
  print('Period 2 Valid Pixels: ' + count2);

  if (count1 === 0 || count2 === 0) {
    print('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - Get mean NO2 values
  var val1 = mean_no2_1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  var val2 = mean_no2_2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  // 5. Validation & Final Answer
  print('Feb 10-25 Mean NO2: ' + val1.toFixed(6));
  print('Apr 20-May 12 Mean NO2: ' + val2.toFixed(6));

  // Check for invalid values
  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2) || val1 < 0 || val2 < 0) {
    print('<answer>C3</answer>');
  } else if (val2 > val1) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
